  }

  function clearUnread(device) {
    device.unread = 0;
    var badge = device.tab.querySelector(".badge");
    if (badge) {
      badge.remove();
    }
  }

  function createDevice(name) {
    if (state.devices[name]) {
      return state.devices[name];
    }

    state.deviceSequence++;
    var controlId = "device-" + state.deviceSequence;

    var tab = document.createElement("button");
    tab.type = "button";
    tab.className = "tab";
    tab.id = controlId + "-tab";
    tab.setAttribute("role", "tab");
    tab.setAttribute("aria-controls", controlId + "-panel");
    tab.setAttribute("aria-selected", "false");

    var tabName = document.createElement("span");
    tabName.textContent = name;
    tab.appendChild(tabName);

    var total = document.createElement("span");
    total.className = "tab-total";
    total.textContent = "(0)";
    tab.appendChild(total);
    elements.tabs.appendChild(tab);

    var panel = document.createElement("section");
    panel.className = "log-panel";
    panel.id = controlId + "-panel";
    panel.setAttribute("role", "tabpanel");
    panel.setAttribute("aria-labelledby", tab.id);

    var lines = document.createElement("div");
    lines.className = "log-lines";
    lines.setAttribute("aria-live", "off");

    var footer = document.createElement("footer");
    footer.className = "panel-footer";

    var controls = document.createElement("div");
    controls.className = "footer-controls";

    var scrollControl = document.createElement("label");
    scrollControl.className = "checkbox-control";
    var scrollCheckbox = document.createElement("input");
    scrollCheckbox.type = "checkbox";
    scrollCheckbox.checked = true;
    scrollControl.appendChild(scrollCheckbox);
    scrollControl.appendChild(document.createTextNode("Auto-scroll"));

    var filter = document.createElement("select");
    filter.className = "filter-select";
    filter.setAttribute("aria-label", "Minimum log level for " + name);

    var filterOptions = [
      { value: "0", text: "ALL" },
      { value: "1", text: "INFO+" },
      { value: "2", text: "WARN+" },
      { value: "3", text: "ERROR+" },
      { value: "4", text: "CRITICAL" }
    ];

    for (var i = 0; i < filterOptions.length; i++) {
      var option = document.createElement("option");
      option.value = filterOptions[i].value;
      option.textContent = filterOptions[i].text;
      filter.appendChild(option);
    }

    controls.appendChild(scrollControl);
    controls.appendChild(filter);

    var renderCount = document.createElement("span");
    renderCount.className = "render-count";
    controls.appendChild(renderCount);

    var actions = document.createElement("div");
    actions.className = "footer-actions";

    var exportButton = document.createElement("button");
    exportButton.type = "button";
    exportButton.className = "btn";
    exportButton.textContent = "Export";

    var clearButton = document.createElement("button");
    clearButton.type = "button";
    clearButton.className = "btn danger";
    clearButton.textContent = "Clear";

    actions.appendChild(exportButton);
    actions.appendChild(clearButton);
    footer.appendChild(controls);
    footer.appendChild(actions);
    panel.appendChild(lines);
    panel.appendChild(footer);
    elements.logArea.appendChild(panel);

    var device = {
      name: name,
      tab: tab,
      totalElement: total,
      panel: panel,
      lines: lines,
      filter: filter,
      renderCount: renderCount,
      autoScroll: scrollCheckbox,
      clearButton: clearButton,
      unread: 0,
      total: 0,
      rendered: 0,
      lastTimestamp: ""
    };
    state.devices[name] = device;

    tab.addEventListener("click", function () {
      switchTab(name);
    });
    filter.addEventListener("change", function () {
      applyFilter(name);
    });
    scrollCheckbox.addEventListener("change", function () {
      if (scrollCheckbox.checked) {
        scrollToLatest(device);
      }
    });
    exportButton.addEventListener("click", function () {
      exportDevice(name);
    });
    clearButton.addEventListener("click", function () {
      clearDevice(name);
    });

    if (!state.activeDevice) {
      switchTab(name);
    }

    updatePlaceholder();
    return device;
  }

  function switchTab(name) {
    var nextDevice = state.devices[name];
    if (!nextDevice) {
      return;
    }

    if (state.activeDevice && state.devices[state.activeDevice]) {
      var currentDevice = state.devices[state.activeDevice];
      currentDevice.tab.classList.remove("active");
      currentDevice.tab.setAttribute("aria-selected", "false");
      currentDevice.panel.classList.remove("active");
    }

    state.activeDevice = name;
    nextDevice.tab.classList.add("active");
    nextDevice.tab.setAttribute("aria-selected", "true");
    nextDevice.panel.classList.add("active");
    clearUnread(nextDevice);

    if (nextDevice.lastTimestamp) {
      writeMarker(name, nextDevice.lastTimestamp);
    }

    if (nextDevice.autoScroll.checked) {
      scrollToLatest(nextDevice);
    }
  }

  function appendEntry(
    rawEntry,
    isLive,
    deferDashboardUpdate,
    countTowardTotal
  ) {
    var entry = normalizeEntry(rawEntry);
    if (!entry) {
      return false;
    }

    var key = entryKey(entry);
    if (state.seenEntries[key]) {
      return false;
    }
    state.seenEntries[key] = entry.device;

    var device = createDevice(entry.device);
    var line = document.createElement("div");
    line.className = "log-line";
    line.dataset.level = String(entry.level);
    line.dataset.entryKey = key;

    var levelName = LEVEL_NAMES[entry.level];
    line.textContent =
      "[" +
      formatTimestamp(entry.timestamp) +
      "] " +
      (levelName ? "[" + levelName + "] " : "") +
      entry.message;

    var filterMinimum = parseInt(device.filter.value, 10);
    if (filterMinimum > 0 && entry.level < filterMinimum) {
      line.classList.add("level-hidden");
    }

    device.lines.appendChild(line);
    device.rendered++;
    if (countTowardTotal !== false) {
      device.total++;
    }

    while (device.rendered > MAX_RENDERED_LINES) {
      var oldestLine = device.lines.firstElementChild;
      if (!oldestLine) {
        break;
      }
      delete state.seenEntries[oldestLine.dataset.entryKey];
      oldestLine.remove();
      device.rendered--;
    }

    if (!(deferDashboardUpdate && countTowardTotal === false)) {
      updateDeviceCounts(device);
    }
    if (entry.timestamp > device.lastTimestamp) {
      device.lastTimestamp = entry.timestamp;
    }

    if (entry.device === state.activeDevice) {
      writeMarker(entry.device, entry.timestamp);
      if (device.autoScroll.checked && !deferDashboardUpdate) {
        scrollToLatest(device);
      }
    } else if (isLive && state.historyLoaded) {
      device.unread++;
      createBadge(device);
    }

    if (!deferDashboardUpdate) {
      updateDashboard();
    }
    return true;
  }

  function applyFilter(name) {
    var device = state.devices[name];
    if (!device) {
      return;
    }

    var filterMinimum = parseInt(device.filter.value, 10);
    var lines = device.lines.querySelectorAll(".log-line");

    for (var i = 0; i < lines.length; i++) {
      var lineLevel = parseInt(lines[i].dataset.level, 10);
      if (!Number.isInteger(lineLevel)) {
        lineLevel = 0;
      }
      lines[i].classList.toggle(
        "level-hidden",
        filterMinimum > 0 && lineLevel < filterMinimum
      );
    }
  }

  function exportDevice(name) {
    var device = state.devices[name];
    if (!device) {
      return;
    }

    var visibleLines = device.lines.querySelectorAll(
      ".log-line:not(.level-hidden)"
    );
    var output = [];
    for (var i = 0; i < visibleLines.length; i++) {
      output.push(visibleLines[i].textContent);
    }

    var blob = new Blob([output.join("\\n") + (output.length ? "\\n" : "")], {
      type: "text/plain;charset=utf-8"
    });
    var downloadUrl = URL.createObjectURL(blob);
    var link = document.createElement("a");
    link.href = downloadUrl;
    link.download = name.replace(/[^a-z0-9._-]+/gi, "_") + "_logs.txt";
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(function () {
      URL.revokeObjectURL(downloadUrl);
    }, 0);
  }

  function resetDevice(device) {
    var seenKeys = Object.keys(state.seenEntries);
    for (var i = 0; i < seenKeys.length; i++) {
      if (state.seenEntries[seenKeys[i]] === device.name) {
        delete state.seenEntries[seenKeys[i]];
      }
    }

    device.lines.textContent = "";
    device.total = 0;
    device.rendered = 0;
    device.unread = 0;
    device.lastTimestamp = "";
    updateDeviceCounts(device);
    clearUnread(device);
    removeMarker(device.name);
    updateDashboard();
  }

  function clearDevice(name) {
    var device = state.devices[name];
    if (!device || device.clearButton.disabled) {
      return;
    }

    if (!window.confirm("Clear all stored logs for " + name + "?")) {
      return;
    }

    device.clearButton.disabled = true;
    fetch(endpointUrl("clear"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ device: name })
    })
      .then(function (response) {
        if (!response.ok) {
          throw new Error("Clear request returned HTTP " + response.status);
        }
        resetDevice(device);
        showNotice("Cleared stored logs for " + name + ".", "success", true);
        syncHistory();
      })
      .catch(function () {
        showNotice(
          "Could not clear logs for " + name + ". The stored logs were not changed.",
          "error",
          false
        );
      })
      .finally(function () {
        device.clearButton.disabled = false;
      });
  }

  function restoreUnreadCounts(logs) {
    var deviceNames = Object.keys(logs);

    for (var i = 0; i < deviceNames.length; i++) {
      var name = deviceNames[i];
      if (name === state.activeDevice || !state.devices[name]) {
        continue;
      }

      var lastRead = readMarker(name);
      var entries = Array.isArray(logs[name]) ? logs[name] : [];
      var unread = 0;

      for (var j = 0; j < entries.length; j++) {
        if (!lastRead || entries[j].timestamp > lastRead) {
          unread++;
        }
      }

      if (unread > 0) {
        state.devices[name].unread = unread;
        createBadge(state.devices[name]);
      }
    }
  }

  function flushQueuedEntries() {
    var queued = state.queuedEntries;
    state.queuedEntries = [];

    for (var i = 0; i < queued.length; i++) {
      appendEntry(queued[i], true, true);
    }
    updateDashboard();
    if (state.activeDevice && state.devices[state.activeDevice]) {
      scrollToLatest(state.devices[state.activeDevice]);
    }
  }

  function scheduleHistorySync(delay) {
    window.clearTimeout(state.historyTimer);
    state.historyTimer = window.setTimeout(syncHistory, delay);
  }

  function syncHistory() {
    if (state.historySyncInProgress) {
      state.historySyncRequested = true;
      return;
    }

    state.historySyncInProgress = true;
    window.clearTimeout(state.historyTimer);
    var firstLoad = !state.historyLoaded;

    fetch(endpointUrl("logs"), { cache: "no-store" })
      .then(function (response) {
        if (!response.ok) {
          throw new Error("History request returned HTTP " + response.status);
        }
        return response.json();
      })
      .then(function (logs) {
        if (!logs || Array.isArray(logs) || typeof logs !== "object") {
          throw new Error("History response is not an object");
        }

        var deviceNames = Object.keys(logs);
        for (var i = 0; i < deviceNames.length; i++) {
          var deviceName = deviceNames[i];
          var entries = Array.isArray(logs[deviceName])
            ? logs[deviceName]
            : [];
          var device = createDevice(deviceName);
          var firstRenderedIndex = Math.max(
            0,
            entries.length - MAX_RENDERED_LINES
          );

          for (var j = firstRenderedIndex; j < entries.length; j++) {
            appendEntry(entries[j], !firstLoad, true, false);
          }

          device.total = entries.length;
          updateDeviceCounts(device);
        }

        if (firstLoad) {
          restoreUnreadCounts(logs);
        }

        state.historyLoaded = true;
        flushQueuedEntries();
        clearNotice();
      })
      .catch(function () {
        if (!state.historyLoaded) {
          state.historyLoaded = true;
          flushQueuedEntries();
        }
        showNotice(
          "Stored log history is unavailable. Live messages will continue when the stream is connected.",
          "error",
          false
        );
        scheduleHistorySync(HISTORY_RETRY_MS);
      })
      .finally(function () {
        state.historySyncInProgress = false;
        updateDashboard();
        if (state.historySyncRequested) {
          state.historySyncRequested = false;
          scheduleHistorySync(0);
        }
      });
  }

  function scheduleReconnect() {
    if (state.reconnectTimer) {
      return;
    }

    var delay = state.reconnectDelay;
    state.reconnectDelay = Math.min(state.reconnectDelay * 2, RECONNECT_MAX_MS);
    state.reconnectTimer = window.setTimeout(function () {
      state.reconnectTimer = null;
      connectWebSocket();
    }, delay);
  }

  function connectWebSocket() {
    if (
      state.socket &&
      (state.socket.readyState === WebSocket.OPEN ||
        state.socket.readyState === WebSocket.CONNECTING)
    ) {
      return;
    }

    setConnectionStatus(
      state.historyLoaded ? "Reconnecting" : "Connecting",
      "warning"
    );

    var socket;
    try {
      socket = new WebSocket(websocketUrl());
    } catch (error) {
      setConnectionStatus("Offline", "error");
      scheduleReconnect();
      return;
    }

    state.socket = socket;

    socket.addEventListener("open", function () {
      state.reconnectDelay = RECONNECT_MIN_MS;
      setConnectionStatus("Live", "live");
      syncHistory();
    });

    socket.addEventListener("message", function (event) {
      try {
        var entry = JSON.parse(event.data);
        if (!state.historyLoaded || state.historySyncInProgress) {
          state.queuedEntries.push(entry);
        } else {
          appendEntry(entry, true, false);
        }
      } catch (error) {
        showNotice(
          "A live message could not be read. Waiting for the next history sync.",
          "error",
          false
        );
      }
    });

    socket.addEventListener("error", function () {
      setConnectionStatus("Connection error", "error");
    });

    socket.addEventListener("close", function () {
      if (state.socket === socket) {
        state.socket = null;
      }
      setConnectionStatus("Reconnecting", "warning");
      scheduleReconnect();
      scheduleHistorySync(RECONNECT_MIN_MS);
    });
  }

  updateDashboard();
  connectWebSocket();
  scheduleHistorySync(1200);
})();
</script>

</body>
</html>
